<?php /** The source form (source-add / source-edit; ids source-form-field-{name}; the connector's sub-form source-form-{connector}, every one rendered — the script shows the chosen one; JavaScript off shows them all with the chosen marked). Data: cur, settings, connector, locked, mappings, back */
$isNew = $cur === null; $sf = $settings['sftp'] ?? []; $v = static fn ($x) => e((string) ($x ?? ''));
$intakeBox = (string) env('RI_INTAKE_MAILBOX', '');
?>
<?= view('shared/header.php', ['id' => $isNew ? 'source-add' : 'source-edit', 'title' => $isNew ? 'New POS source' : 'Edit ' . $cur['name'], 'crumbs' => [['Home', '/'], ['POS sources', '/sales/sources/'], [$isNew ? 'New' : $cur['name'], null]], 'back' => $back]) ?>
<div class="main-content" id="<?= $isNew ? 'source-add' : 'source-edit' ?>-content">
