            <div class="row mb-3 align-items-center"><div class="col-lg-4"><label class="fw-semibold" for="source-form-field-connector">Connector</label></div><div class="col-lg-8">
                <select name="connector" id="source-form-field-connector" class="form-select btn-touch" <?= $locked ? 'disabled' : '' ?>>
                    <option value="file" <?= $connector === 'file' ? 'selected' : '' ?>>A file — upload, email or SFTP</option>
                    <option value="square" <?= $connector === 'square' ? 'selected' : '' ?>>Square (Orders API)</option>
                    <?php foreach (RI_POS_EXTENDED as $k => $l): ?><option value="<?= $k ?>" disabled><?= e($l) ?> — Extended (use its file export)</option><?php endforeach; ?>
                </select><?php if ($locked): ?><input type="hidden" name="connector" value="<?= e($connector) ?>"><div class="form-text">The connector is fixed once a pull exists.</div><?php endif; ?></div></div>
            <fieldset class="border rounded p-3 mb-3 pos-subform <?= $connector === 'file' ? 'pos-subform-chosen' : '' ?>" id="source-form-file" data-connector="file">
                <legend class="fs-12 fw-semibold float-none w-auto px-1 mb-0">A file<?= $connector === 'file' ? ' — chosen' : '' ?></legend>
                <div class="row mb-2 align-items-center"><div class="col-lg-4"><label for="source-form-field-mapping-key">Mapping</label></div><div class="col-lg-8"><select name="settings_mapping_key" id="source-form-field-mapping-key" class="form-select btn-touch"><?php foreach ($mappings as $m): ?><option value="<?= e($m['key']) ?>" <?= ($settings['mapping_key'] ?? 'generic') === $m['key'] ? 'selected' : '' ?>><?= e($m['name']) ?> (<?= e($m['key']) ?>)</option><?php endforeach; ?></select></div></div>
                <div class="row mb-2 align-items-center"><div class="col-lg-4"><label for="source-form-field-intake">How the file arrives</label></div><div class="col-lg-8"><select name="settings_intake" id="source-form-field-intake" class="form-select btn-touch"><?php foreach (SOURCE_INTAKES as $k => $l): ?><option value="<?= $k ?>" <?= ($settings['intake'] ?? 'upload') === $k ? 'selected' : '' ?>><?= e(ucfirst($l)) ?></option><?php endforeach; ?></select>
                    <div class="form-text" id="source-form-intake-address">Email: the POS mails its export to <strong><?= $intakeBox !== '' ? e($intakeBox) : 'the intake mailbox (RI_INTAKE_MAILBOX is not set yet)' ?></strong> from the sender named below.</div></div></div>
                <div class="row mb-2 align-items-center"><div class="col-lg-4"><label for="source-form-field-email-from">Sender (email)</label></div><div class="col-lg-8"><input type="text" name="settings_email_from" id="source-form-field-email-from" class="form-control btn-touch" value="<?= $v($settings['email_from'] ?? '') ?>" placeholder="reports@pos.example or pos.example"></div></div>
                <div class="row mb-2 align-items-center"><div class="col-lg-4"><label for="source-form-field-sftp-host">SFTP host · port</label></div><div class="col-lg-8"><div class="input-group"><input type="text" name="settings_sftp_host" id="source-form-field-sftp-host" class="form-control btn-touch" value="<?= $v($sf['host'] ?? '') ?>" placeholder="sftp.pos.example"><input type="number" name="settings_sftp_port" id="source-form-field-sftp-port" class="form-control btn-touch" style="max-width:6rem" value="<?= $v($sf['port'] ?? '') ?>" placeholder="22" min="1" max="65535"></div></div></div>
                <div class="row mb-2 align-items-center"><div class="col-lg-4"><label for="source-form-field-sftp-path">SFTP folder · files</label></div><div class="col-lg-8"><div class="input-group"><input type="text" name="settings_sftp_path" id="source-form-field-sftp-path" class="form-control btn-touch" value="<?= $v($sf['path'] ?? '') ?>" placeholder="/exports"><input type="text" name="settings_sftp_pattern" id="source-form-field-sftp-pattern" class="form-control btn-touch" style="max-width:10rem" value="<?= $v($sf['pattern'] ?? '') ?>" placeholder="sales_*.csv"></div></div></div>
                <div class="row mb-2 align-items-center"><div class="col-lg-4"><label for="source-form-field-sftp-user">SFTP user</label></div><div class="col-lg-8"><input type="text" name="settings_sftp_user" id="source-form-field-sftp-user" class="form-control btn-touch" value="<?= $v($sf['user'] ?? '') ?>"><div class="form-text">The password or key is set apart, sealed — on the source's credential page.</div></div></div>
                <div class="row mb-2 align-items-center"><div class="col-lg-4"><label for="source-form-field-delimiter">Delimiter</label></div><div class="col-lg-8"><input type="text" name="settings_delimiter" id="source-form-field-delimiter" class="form-control btn-touch" maxlength="2" style="max-width:6rem" value="<?= $v($settings['delimiter'] ?? '') ?>" placeholder="auto"></div></div>
                <div class="form-check"><input type="hidden" name="settings_keep_files" value="no"><input type="checkbox" class="form-check-input" name="settings_keep_files" value="yes" id="source-form-field-keep-files" <?= ($settings['keep_files'] ?? true) ? 'checked' : '' ?>><label class="form-check-label" for="source-form-field-keep-files">Keep each file on its pull</label></div>
            </fieldset>
            <fieldset class="border rounded p-3 mb-3 pos-subform <?= $connector === 'square' ? 'pos-subform-chosen' : '' ?>" id="source-form-square" data-connector="square">
                <legend class="fs-12 fw-semibold float-none w-auto px-1 mb-0">Square<?= $connector === 'square' ? ' — chosen' : '' ?></legend>
                <div class="row mb-2 align-items-center"><div class="col-lg-4"><label for="source-form-field-location-id">Location id</label></div><div class="col-lg-8"><input type="text" name="settings_location_id" id="source-form-field-location-id" class="form-control btn-touch" value="<?= $v($settings['location_id'] ?? '') ?>" placeholder="L…"></div></div>
                <div class="row mb-2 align-items-center"><div class="col-lg-4"><label for="source-form-field-base-url">Base URL</label></div><div class="col-lg-8"><input type="url" name="base_url" id="source-form-field-base-url" class="form-control btn-touch" value="<?= $v($cur['base_url'] ?? '') ?>" placeholder="https://connect.squareup.com"></div></div>
                <div class="row mb-2 align-items-center"><div class="col-lg-4"><label for="source-form-field-lookback-days">Look back (days)</label></div><div class="col-lg-8"><input type="number" name="settings_lookback_days" id="source-form-field-lookback-days" class="form-control btn-touch" min="1" max="30" style="max-width:6rem" value="<?= $v($settings['lookback_days'] ?? '') ?>" placeholder="3"><div class="form-text">Square back-dates edits: each pull reads this many days before the last good one.</div></div></div>
            </fieldset>
            <div class="row mb-3 align-items-center"><div class="col-lg-4"><label class="fw-semibold" for="source-form-field-schedule-minutes">Pull every (minutes)</label></div><div class="col-lg-8"><input type="number" name="schedule_minutes" id="source-form-field-schedule-minutes" class="form-control btn-touch" min="0" max="10080" style="max-width:8rem" value="<?= $v($cur === null ? '' : (string) (int) $cur['schedule_minutes']) ?>" placeholder="0"><div class="form-text">0 = on arrival (an upload, an email). SFTP and Square: 60 by default.</div></div></div>
