        <div class="card-footer d-flex gap-2"><button type="submit" class="btn btn-primary btn-touch" id="source-form-save"><?= $isNew ? 'Add the source' : 'Save' ?></button><?= hx_link($isNew ? '/sales/sources/' : '/sales/sources/' . (int) $cur['id'], 'Cancel', 'btn btn-light btn-touch', 'id="source-form-cancel"') ?></div>
    </form>
</div>
